#!/usr/bin/env python3
"""Direct call tree over the C++ generated by rexglue. Usage: call_tree.py <generated dir> <func> [depth] [min_lines]"""
import re, glob, sys, pickle, os
d, root = sys.argv[1], sys.argv[2]
maxd = int(sys.argv[3]) if len(sys.argv) > 3 else 2
minl = int(sys.argv[4]) if len(sys.argv) > 4 else 40
txt = {}
for f in glob.glob(d + '/eden_recomp.*.cpp'):
    s = open(f).read()
    for m in re.finditer(r'DEFINE_REX_FUNC\((\w+)\) \{(.*?)\n\}\n', s, re.S): txt[m.group(1)] = m.group(2)
def calls(fn):
    out = []
    for c in re.findall(r'[\t ](\w+)\(ctx, base\);', txt.get(fn, '')):
        if c not in out and not c.startswith('__s') and not c.startswith('__r'): out.append(c)
    return out
seen = set()
def show(fn, depth):
    cs = calls(fn); body = txt.get(fn, '')
    print('  ' * depth + f"{fn} [{body.count(chr(10))} lines, {body.count('REX_CALL_INDIRECT')} ind] -> " + ', '.join(cs[:30]) + (' ...' if len(cs) > 30 else ''))
    if depth < maxd:
        for c in cs[:30]:
            if c in txt and c not in seen and txt[c].count('\n') > minl:
                seen.add(c); show(c, depth + 1)
show(root, 0)
